            edge = (nx == 0 or nx == w - 1 or ny == 0 or ny == h - 1)
            return (12.0 * adj_self + 2.0 * (3 - d_opp // 2) + 8.0 * adj_opp
                    - 3.5 * max(0, adj_opp - adj_self) + (2.0 if edge else 0.0) - 0.05 * d_opp)
